// Regenerates src/data/affiliates.ts from the handoff /go/ link list, so the redirects are
// always exactly the source table (never edited by hand).
//
//   node scripts/generate-go-links.mjs <path to sokefi_go_links_launch15.md>
//
// - "Ready to set up" rows become plain redirects; rows whose programme says "referral" are
//   flagged `referral: true` (no commission, never gets tracking).
// - SPECIAL holds the keys in "Needs a decision or special setup", and OVERRIDES any
//   destination Veronica has changed after the table was written. Both are listed in the
//   generated file so nothing is hidden.
import fs from 'node:fs';

const SPECIAL = {
  // Provider home page until the Booking.com listing is chosen.
  'booking-karma-st-martins': { destination: 'https://www.booking.com/', partner: 'booking.com' },
  'booking-darwins-townhouse': { destination: 'https://www.booking.com/', partner: 'booking.com' },
  // Region split, resolved per reader in src/pages/go/[slug].astro: Allianz only sells to
  // US residents and Staysure only to UK residents; anyone else gets "link unavailable".
  'travel-insurance': {
    destination: {
      us: 'https://www.allianztravelinsurance.com/',
      uk: 'https://www.staysure.co.uk/',
    },
    partner: 'allianztravelinsurance.com / staysure.co.uk',
  },
};

/** @type {Record<string, string>} key → destination, when it must differ from the table. */
const OVERRIDES = {};

const source = process.argv[2];
if (!source) {
  console.error('Usage: node scripts/generate-go-links.mjs <path to sokefi_go_links_launch15.md>');
  process.exit(1);
}
const md = fs.readFileSync(source, 'utf8').replace(/\r\n/g, '\n');
const start = md.indexOf('## Ready to set up');
const end = md.indexOf('## Needs a decision');
if (start < 0 || end < 0) throw new Error('Could not find the "Ready to set up" table');

const rows = [...md.slice(start, end).matchAll(/^\| `([^`]+)` \| (\S+) \| ([^|]*)\|/gm)].map(
  ([, key, url, programme]) => ({ key, url, referral: /referral/i.test(programme) }),
);
const keys = rows.map((r) => r.key);
const dupes = keys.filter((k, i) => keys.indexOf(k) !== i);
if (dupes.length) throw new Error(`Duplicate keys in the table: ${dupes.join(', ')}`);
for (const k of Object.keys(SPECIAL)) {
  if (keys.includes(k)) throw new Error(`"${k}" is in the Ready table and also in SPECIAL`);
}
for (const k of Object.keys(OVERRIDES)) {
  if (!keys.includes(k)) throw new Error(`Override "${k}" is not in the Ready table`);
}

const site = (url) => new URL(url).hostname.replace(/^(www|us|en|esim|store|electronics)\./, '');
const quote = (s) => `'${s.replace(/'/g, "\\'")}'`;
const entry = ({ key, url, referral }) => {
  const destination = OVERRIDES[key] ?? url;
  return [
    `  ${quote(key)}: {`,
    ...(OVERRIDES[key] ? [`    // Override: the source table says ${url}`] : []),
    `    destination: ${quote(destination)},`,
    `    partner: ${quote(site(destination))},`,
    ...(referral ? ['    referral: true,'] : []),
    '  },',
  ].join('\n');
};
const special = Object.entries(SPECIAL).map(([key, value]) =>
  [
    `  ${quote(key)}: {`,
    typeof value.destination === 'string'
      ? `    destination: ${quote(value.destination)},`
      : `    destination: {\n      us: ${quote(value.destination.us)},\n      uk: ${quote(value.destination.uk)},\n    },`,
    `    partner: ${quote(value.partner)},`,
    '  },',
  ].join('\n'),
);

const file = `// GENERATED by scripts/generate-go-links.mjs from the handoff /go/ link list
// (website_handoff_batch1/sokefi_go_links_launch15.md). Do not edit by hand — update the
// source table and re-run the script.
//
// /go/<key> redirects (src/pages/go/[slug].astro). Untracked for now: each key sends the
// reader straight to the destination. Tracked affiliate links replace these at Phase B.
// \`referral: true\` marks links that never earn commission and must never get tracking.
// A destination can be split by reader market ({ us, uk }): US readers get \`us\`, UK readers
// \`uk\`, and anyone else gets "link unavailable" (getReaderMarket in src/utils/visitorRegion.ts).

export interface RegionalDestination {
  /** US readers. */
  us: string;
  /** UK readers. */
  uk: string;
}

export interface GoLink {
  destination: string | RegionalDestination;
  partner: string;
  referral?: boolean;
}

export const AFFILIATES: Record<string, GoLink> = {
  // --- Ready to set up (${rows.length}) ---
${rows.map(entry).join('\n')}

  // --- Special setup (${Object.keys(SPECIAL).length}) ---
${special.join('\n')}
};

export type AffiliateSlug = keyof typeof AFFILIATES;
`;
fs.writeFileSync('src/data/affiliates.ts', file);
console.log(
  `Wrote src/data/affiliates.ts: ${rows.length} ready + ${Object.keys(SPECIAL).length} special = ${rows.length + Object.keys(SPECIAL).length} keys (${rows.filter((r) => r.referral).length} referral, ${Object.keys(OVERRIDES).length} override)`,
);
